// === Tab: mySketch ===
let N = 32*32*32;
let vfbWide, vfbHigh, fbOldVoxels, fbNewVoxels;
let ffbWide, ffbHigh, fbFaces;
let updateShdr, faceShdr, drawShdr;

function setup() {
	let s = max(windowWidth, windowHeight);
	createCanvas(s*4/3, s, WEBGL);

	vfbWide = 1024;
	vfbHigh = int(ceil(34*34*34/1024));
	let fbOptions = { format: UNSIGNED_BYTE,
	  	    				  depth: false, antialias: false, density: 1,
					    		  width: vfbWide, height: vfbHigh };
	fbOldVoxels = createFramebuffer( fbOptions );
	fbNewVoxels = createFramebuffer( fbOptions );
	fbOldVoxels.begin();
	let gl = fbOldVoxels.gl;
	gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
	fbOldVoxels.loadPixels();
	for( let z=0; z<34; z++ ) {
		for( let y=0; y<34; y++ ) {
			for( let x=0; x<34; x++ ) {
				let idx = (((z*34)+y)*34+x)*4;
				fbOldVoxels.pixels[idx  ] = random(128, 255);
				fbOldVoxels.pixels[idx+1] = random(128, 255);
				fbOldVoxels.pixels[idx+2] = random(128, 255);
				fbOldVoxels.pixels[idx+3] = 0;
			}
		}
	}
	fbOldVoxels.updatePixels();
	fbOldVoxels.end();

	ffbWide = 1024;
	ffbHigh = int(ceil(32*32*32*6/1024));
	fbOptions = { format: UNSIGNED_BYTE,
	    				  depth: false, antialias: false, density: 1,
			    		  width: ffbWide, height: ffbHigh };
	fbFaces = createFramebuffer( fbOptions );

	updateShdr = createShader( vsUpdate, fsUpdate );
	faceShdr = createShader( vsUpdate, fsFace );
	drawShdr = createShader( vsDraw, fsDraw );

	camera( 0, 0, 3,  0, 0.1, 0,  0, 1, 0 );
}

function windowResized() {
  let canvasSize = max(windowWidth, windowHeight);
  resizeCanvas( canvasSize*4/3, canvasSize );
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

function draw() {
	let t = frameCount/60.0;
	//t = 0.0;

	fbNewVoxels.begin();
	updateShdr.bindShader();
	updateShdr.setUniform( 'voxels', fbOldVoxels );
	updateShdr.setUniform( 'time', t );
	updateShdr.bindTextures();
	gl = fbNewVoxels.gl;
	gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
	gl.drawArrays( gl.TRIANGLES, 0, 3 );  // a single full-screen triangle
	updateShdr.unbindTextures();
	updateShdr.unbindShader();
	fbNewVoxels.end();

	fbFaces.begin();
	faceShdr.bindShader();
	faceShdr.setUniform( 'voxels', fbNewVoxels );
	faceShdr.bindTextures();
	gl = fbFaces.gl;
	gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
	gl.drawArrays( gl.TRIANGLES, 0, 3 );  // a single full-screen triangle
	faceShdr.unbindTextures();
	faceShdr.unbindShader();
	fbFaces.end();

	background(0);
	perspective( PI/4, 1.0*width/height, 0.01, 10 );
	orbitControl();
	rotateX( PI*0.5-0.5 );  // orient +z up, +x east, +y south
	rotateZ( TAU*0.05*t );

	gl = this._renderer.GL;
	drawShdr.bindShader();
	drawShdr.setUniform( 'voxels', fbOldVoxels );
	drawShdr.setUniform( 'faces', fbFaces );
	drawShdr.bindTextures();
	gl.enable( gl.CULL_FACE );
	gl.frontFace( gl.CW );
	gl.drawArraysInstanced( gl.TRIANGLE_STRIP, 0, 4, 6*N );
	gl.disable( gl.CULL_FACE );
	drawShdr.unbindTextures();
	drawShdr.unbindShader();

	let temp = fbOldVoxels;
	fbOldVoxels = fbNewVoxels;
	fbNewVoxels = temp;
}

let vsUpdate = `#version 300 es
precision highp float;
precision highp int;
void main() {
	gl_Position = vec4( 4*ivec2(gl_VertexID&1, gl_VertexID&2)-1, 0., 1. );
}
`;

let fsUpdate = `#version 300 es
precision highp float;
precision highp int;
uniform sampler2D voxels;
uniform float time;
out vec4 fragColor;
#define TAU 6.2831853

vec2 rot2( vec2 p, float a ) {
  return cos(a)*p + sin(a)*vec2(-p.y, p.x);
}

void main() {
  ivec2 dataRes = textureSize( voxels, 0 );
  int idx = int(gl_FragCoord.y) * dataRes.x + int(gl_FragCoord.x);
  vec4 vd = texelFetch( voxels, ivec2(gl_FragCoord.xy), 0 );
	vec3 p = vec3( idx%34, (idx/34)%34, idx/(34*34) )-16.5;
	//float a = length(p)<(11.+5.*sin(TAU*0.02*time)) ? 1. : 0.;
	p.xy = rot2( p.xy, -TAU*0.03*time );
	p.yz = rot2( p.yz, TAU*0.02*time );
	float a = (length(vec2(length(p.xy)-10., p.z))-6. < 0.) ? 1. : 0.;
	a = (7.*vd.a+a)/8.;
	if( a < 1./32. ) a = 0.;
	if( a > 31./32. ) a = 1.;
	fragColor = vec4( vd.rgb, a );
}
`;


let fsFace = `#version 300 es
precision highp float;
precision highp int;
uniform sampler2D voxels;
out vec4 fragColor;

bool isBlock( int i ) {
  return texelFetch( voxels, ivec2( i%1024, i/1024 ), 0 ).a == 1.;
}

const int aoLevels[8] = int[](0, 1, 1, 2, 1, 3, 2, 3 );
int computeAO( int mid, int dx, int dy ) {
	int b = (isBlock(mid-dx) ? 1+256 : 0) + (isBlock(mid-dx-dy) ? 2 : 0) +
					(isBlock(mid-dy) ? 4  : 0) + (isBlock(mid+dx-dy) ? 8 : 0) +
					(isBlock(mid+dx) ? 16 : 0) + (isBlock(mid+dx+dy) ? 32 : 0) +
					(isBlock(mid+dy) ? 64 : 0) + (isBlock(mid-dx+dy) ? 128 : 0);
	return aoLevels[ b & 7 ] + 
	      (aoLevels[ (b>>2) & 7 ]<<2) +
				(aoLevels[ (b>>6) & 7 ]<<4) + 
				(aoLevels[ (b>>4) & 7 ]<<6);
}

const int offsets[18] = int[18]( 
	1, -34, -34*34,  -1, 34, -34*34,  // +/- x
	34, 1, -34*34,  -34, -1, -34*34,  // +/- y
	34*34, 1, 34,  -34*34, 1, -34 );  // +/- z
void main() {
  ivec2 dataRes = textureSize( voxels, 0 );
  int faceIdx = int(gl_FragCoord.y) * 1024 + int(gl_FragCoord.x);
	int iFace = faceIdx % 6;
	int iVox = faceIdx / 6;
	ivec3 cubePos = ivec3( iVox&31, (iVox>>5)&31, iVox>>10 ) + 1;
	int voxIdx = (cubePos.z*34+cubePos.y)*34+cubePos.x;
  vec4 vd = texelFetch( voxels, ivec2(voxIdx%1024, voxIdx/1024), 0 );
	if( vd.a == 0. ) {
		fragColor = vec4( vd.rgb, 1. );
		return;
	}
	int iMid = voxIdx + offsets[iFace*3];
	if( texelFetch( voxels, ivec2( iMid%1024, iMid/1024 ), 0 ).a == 1. ) {
		fragColor = vec4( vd.rgb, 1. );
		return;
	}
	int ao = computeAO( iMid, offsets[iFace*3+1], offsets[iFace*3+2] );
  fragColor = vec4( vd.rgb, float(ao)/255. );
}
`;


let vsDraw = `#version 300 es
precision highp float;
precision highp int;
uniform mat4 uModelViewMatrix;
uniform mat4 uNormalMatrix;
uniform mat4 uProjectionMatrix;
uniform sampler2D voxels;
uniform sampler2D faces;
out vec2 uv;
out vec4 vColor;

vec3 hsb2rgb( in vec3 c ) {
   vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0),
                            6.0)-3.0)-1.0,  0.0,  1.0 );
   rgb = rgb*rgb*(3.0-2.0*rgb);
   return c.z * mix( vec3(1.0), rgb, c.y);
}

const int vid[24] = int[]( 
	7, 5, 3, 1,  4, 6, 0, 2,    // +/- x
	6, 7, 2, 3,  5, 4, 1, 0,    // +/- y
	4, 5, 6, 7,  2, 3, 0, 1 );  // +/- z

void main() {
  int iCube = gl_InstanceID / 6;
	ivec3 cubePos = ivec3( iCube&31, (iCube>>5)&31, iCube>>10 );
	int idx = ((cubePos.z+1)*34+(cubePos.y+1))*34+cubePos.x+1;
	vec4 vd = texelFetch( voxels, ivec2( idx&1023, idx>>10 ), 0 );
  int iFace = gl_InstanceID % 6;
  uv = vec2( gl_VertexID&1, (gl_VertexID&2)>>1 );
	int ip = vid[ iFace*4+gl_VertexID ];
	vec4 vPos = vec4( ip&1, (ip>>1)&1, ip>>2, 1. );
	vPos.xyz = (vPos.xyz-0.5) * vd.a + 0.5;
	vPos.xyz += vec3(cubePos);
	vPos.xyz = vPos.xyz/16.-1.;
	vPos = uModelViewMatrix * vPos;
	if( vd.a < 0.01 ) { vPos.xyz = vec3(0.); vd = vec4(0.); }
  gl_Position = uProjectionMatrix * vPos;
	float u = float(iFace)/6.;
	//float d = pow(clamp((4.5+vPos.z)/2.5, 0., 1.), 1.);
	//vec3 c = hsb2rgb( vec3( u, 0.7, d ) );
	vec4 f = texelFetch( faces, ivec2(gl_InstanceID%1024, gl_InstanceID/1024), 0 );
	int fullAO = int(f.a*255.5);
	float ao = 1.-(float((fullAO>>(gl_VertexID*2))&3))/4.;
	//vColor = vec4( vd.rgb * ao, 1. );
	vColor = vec4( vec3(ao), 1. );
}
`;

let fsDraw = `#version 300 es
precision highp float;
in vec2 uv;
in vec4 vColor;
out vec4 fragColor;

float sdBox( in vec2 p, in vec2 b ) {
  vec2 d = abs(p)-b;
  return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}

void main() {
	fragColor = vColor;
	vec2 luv = abs((uv-0.5)*1.75);
	fragColor.rgb *= 1.-pow(max(luv.x, luv.y), 8.);
	//fragColor.rgb *= step(0., sdBox(uv-0.25, vec2(0.1, 0.2) ));
}
`;

